const leads = items.map(item => item.json);

// Загальна кількість
const total_leads = leads.length;

// Кількість по стадіях
const by_stage = {};

// Кількість по менеджерах
const by_owner = {};

let new_leads_count = 0;

for (const lead of leads) {

    // ---------- Stage ----------
    const stage = lead.Lead_Status || "Unknown";

    by_stage[stage] = (by_stage[stage] || 0) + 1;

    if (stage === "New") {
        new_leads_count++;
    }

    // ---------- Owner ----------
    const owner = lead.Owner?.name || "Unknown";

    by_owner[owner] = (by_owner[owner] || 0) + 1;
}

return [
{
    json: {
        total_leads,
        new_leads_count,
        by_stage,
        by_owner
    }
}
];

